// DOCTOR_RECOMMEND_V1 (2026-11-23) — ВРАЧ РЕКОМЕНДУЕТ, РЕГИСТРАТУРА ВЫСТАВЛЯЕТ СЧЁТ.
//
// Владелец: «when button Направить is pressed it should show the services to recommend but
// should not generate invoice as doctors shouldn't, as invoice is generated by registrars, and
// Добавить button here should be recommend. and in reception … all the recommended services
// should appear with the tag that it is recommended by doctor and … already chosen, and registrar
// should tick the needed ones and generate invoice, not ticked should still stay for the next times.»
//
// Кабинет врача открывает тот же мастер в режиме рекомендации (opts.recommend): «Рекомендовать»
// вместо «Добавить», без плательщика, скидок, итога и шагов; «Сохранить рекомендации» пишет
// recommended_services (открытые) — визита и счёта нет. Регистратура в мастере визита видит все
// открытые рекомендации пациента в смете — отмеченными, с подписью «Рекомендовано врачом · имя»;
// снятая галочка убирает строку из сметы, рекомендация остаётся; «Убрать» с подтверждением
// закрывает её навсегда.
//
// Стенд — как у crm-smeta-badge-wizard.test.mjs: настоящие миграции, реестр RPC и компилятор
// /api/db за фальшивым fetch; кто вошёл — USER (врач или регистратор).
import { test } from 'node:test';
import assert from 'node:assert/strict';

class F {
  constructor(t) {
    this.tagName = String(t).toUpperCase(); this.style = {}; this.children = []; this.attrs = {};
    this.className = ''; this._t = ''; this._l = {}; this.dataset = {};
    this.value = ''; this.checked = false; this.disabled = false;
  }
  appendChild(c) { this.children.push(c); c.parentElement = this; return c; }
  append(...cs) { for (const c of cs) if (c) this.appendChild(c); }
  removeChild(c) { const i = this.children.indexOf(c); if (i > -1) this.children.splice(i, 1); return c; }
  get firstChild() { return this.children[0] || null; }
  replaceChildren() { this.children.length = 0; }
  setAttribute(k, v) { this.attrs[k] = String(v); }
  removeAttribute(k) { delete this.attrs[k]; }
  getAttribute(k) { return this.attrs[k] ?? null; }
  hasAttribute(k) { return k in this.attrs; }
  addEventListener(t, fn) { (this._l[t] || (this._l[t] = [])).push(fn); }
  removeEventListener() {}
  dispatchEvent(e) { for (const fn of this._l[e.type] || []) fn(e); return true; }
  click() { this.dispatchEvent({ type: 'click', currentTarget: this, target: this, preventDefault() {}, stopPropagation() {} }); }
  focus() {} blur() {} select() {} scrollTo() {}
  contains() { return false; }
  remove() { if (this.parentElement) this.parentElement.removeChild(this); }
  getBoundingClientRect() { return { top: 0, left: 0, right: 200, bottom: 60, width: 200, height: 60 }; }
  querySelector() { return null; }
  querySelectorAll() { return []; }
  get textContent() { return this._t; }
  set textContent(v) { this._t = String(v); this.children.length = 0; }
  get classList() {
    const s = this;
    return {
      contains: (c) => String(s.className).split(/\s+/).includes(c),
      add(c) { if (!String(s.className).split(/\s+/).includes(c)) s.className = (s.className + ' ' + c).trim(); },
      remove(c) { s.className = String(s.className).split(/\s+/).filter((x) => x && x !== c).join(' '); },
      toggle() {},
    };
  }
  get isConnected() { return true; }
}
class TX extends F { constructor(t) { super('#text'); this.nodeType = 3; this._t = String(t); } }
const mk = (t) => { const e = new F(t); if (String(t).toLowerCase() === 'template') e.content = new F('#fragment'); return e; };
globalThis.Node = F;
globalThis.Event = class { constructor(t, o) { this.type = t; Object.assign(this, o || {}); } };
const TOASTS = [];
const TOAST_EL = mk('div');
Object.defineProperty(TOAST_EL, 'textContent', { get() { return ''; }, set(v) { TOASTS.push(String(v)); }, configurable: true });
globalThis.document = {
  createElement: mk, createElementNS: (_n, t) => mk(t), createTextNode: (t) => new TX(t),
  head: mk('head'), body: mk('body'), documentElement: mk('html'),
  addEventListener() {}, removeEventListener() {}, getElementById(id) { return id === 'toast' ? TOAST_EL : null; },
};
globalThis.localStorage = { getItem: (k) => (k === 'admin.lang' ? 'ru' : null), setItem() {}, removeItem() {}, clear() {} };
globalThis.window = { location: { hostname: 'localhost' }, localStorage: globalThis.localStorage, innerWidth: 1440, innerHeight: 900, addEventListener() {}, open: () => null };
globalThis.MutationObserver = class { observe() {} disconnect() {} };
globalThis.requestAnimationFrame = (fn) => fn();
globalThis.confirm = () => true;
function walk(e, o = []) { for (const c of e.children || []) { o.push(c); walk(c, o); } return o; }
const textOf = (el) => [el, ...walk(el)].map((n) => n._t || '').join(' ');

const { openDb } = await import('../../../../server/db/connection.js');
const { migrate } = await import('../../../../server/db/migrate.js');
const { compile } = await import('../../../../server/db/query-compiler.js');
const { getRpc } = await import('../../../../server/services/rpc/index.js');
const { stampWriteBody } = await import('../../../../server/services/domain/package-lines.js');
const { readableColumns } = await import('../../../../server/db/schema-registry.js');

let USER = { id: 1, role: 'registrar', extra_roles: [] };
let DB = null;
const RPC = [];
globalThis.fetch = async (url, opts) => {
  const u = String(url);
  const body = JSON.parse((opts && opts.body) || '{}');
  const ok = (data) => ({ ok: true, status: 200, json: async () => ({ data }) });
  if (u.startsWith('/api/rpc/')) {
    const name = decodeURIComponent(u.slice('/api/rpc/'.length));
    RPC.push({ name, body });
    const handler = getRpc(name);
    if (!handler) return { ok: false, status: 501, json: async () => ({ error: { message: 'no rpc ' + name } }) };
    try { return ok(await handler(DB, body, USER)); }
    catch (e) { return { ok: false, status: e.status || 500, json: async () => ({ error: { code: e.code, message: e.message, params: e.params } }) }; }
  }
  if (u === '/api/db') {
    stampWriteBody(DB, body);
    let compiled;
    try { compiled = compile(body, USER); }
    catch (e) { return { ok: false, status: 400, json: async () => ({ error: { code: 'bad_request', message: e.message } }) }; }
    const { sql, params, meta } = compiled;
    try {
      if (meta.op === 'select') {
        const rows = DB.prepare(sql).all(...params);
        if (meta.single === 'single') return ok(rows[0]);
        if (meta.single === 'maybe') return ok(rows[0] ?? null);
        return ok(rows);
      }
      if (meta.op === 'insert') {
        const info = DB.prepare(sql).run(...params);
        if (!meta.returning) return ok(null);
        const row = DB.prepare(`SELECT ${readableColumns(meta.table).map((c) => `"${c}"`).join(', ')} FROM "${meta.table}" WHERE rowid = ?`).get(info.lastInsertRowid);
        if (meta.single === 'single') return ok(row);
        if (meta.single === 'maybe') return ok(row ?? null);
        return ok([row]);
      }
      DB.prepare(sql).run(...params);
      return ok(null);
    } catch (e) {
      return { ok: false, status: 500, json: async () => ({ error: { code: 'internal', message: e.message } }) };
    }
  }
  return { ok: false, status: 404, json: async () => ({ error: { message: 'no route ' + u } }) };
};
const SPM = await import('../views/service-picker-modal.js?v=ownrep4');
const { openVisitWizard } = await import('../views/visit-wizard.js');
const isWizard = (n) => !!(n && n.style && n.style.position === 'fixed');
const flush = async (n = 12) => { for (let i = 0; i < n; i++) await new Promise((r) => setTimeout(r, 0)); };
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const attrNodes = (root, attr) => [root, ...walk(root)].filter((n) => n.attrs && Object.prototype.hasOwnProperty.call(n.attrs, attr));
const flat = (n) => textOf(n).replace(/\s+/g, ' ').trim();
const btnByText = (root, text) => walk(root).find((n) => n.tagName === 'BUTTON' && flat(n) === text);
const settle = async () => { await flush(20); await wait(60); await flush(20); };

const DOCTOR = { id: 2, role: 'doctor', extra_roles: [] };
const REGISTRAR = { id: 1, role: 'registrar', extra_roles: [] };

/** Пациент 3; анализы 41 «Svc-АЧТВ», 42 «Svc-ОАК» (без врача); врач 2; рекомендации — по списку. */
function seed({ recs = [] } = {}) {
  const db = openDb(':memory:');
  migrate(db);
  db.prepare("INSERT INTO users (id, username, password_hash, full_name, role, is_doctor) VALUES (1,'reg','x','Регистратор','registrar',0)").run();
  db.prepare("INSERT INTO users (id, username, password_hash, full_name, role, is_doctor) VALUES (2,'doc','x','Врачев Доктор','doctor',1)").run();
  db.prepare("INSERT INTO patients (id, full_name, phone) VALUES (3,'Тест-Пациент','+998901112233')").run();
  db.prepare("INSERT INTO services (id, name, price, duration_minutes, type, requires_doctor, is_lab) VALUES (41,'Svc-АЧТВ',35000,30,'lab',0,1)").run();
  db.prepare("INSERT INTO services (id, name, price, duration_minutes, type, requires_doctor, is_lab) VALUES (42,'Svc-ОАК',30000,30,'lab',0,1)").run();
  for (const r of recs) {
    db.prepare(`INSERT INTO recommended_services (patient_id, service_id, service_name, recommended_by, recommended_by_name, notes, status)
                VALUES (3, ?, ?, 2, 'Врачев Доктор', ?, 'pending')`).run(r.service_id, r.name, r.notes || null);
  }
  if (DB) DB.close();
  DB = db;
  SPM.forgetSlots();
}
async function open(user, opts = {}, cfg = {}) {
  seed(cfg);
  USER = user;
  document.body.children.length = 0; TOASTS.length = 0; RPC.length = 0;
  const saved = [];
  await openVisitWizard((res) => { saved.push(res); }, { id: 3, full_name: 'Тест-Пациент', phone: '+998901112233' }, opts);
  await settle();
  const ov = () => document.body.children.find(isWizard);
  assert.ok(ov(), 'мастер не открылся');
  return { ov, saved };
}
const openRecs = () => DB.prepare("SELECT service_id, status, notes, recommended_by FROM recommended_services WHERE patient_id = 3 ORDER BY service_id").all();
async function recommend(ov, name) {
  const row = walk(ov()).find((n) => n.children && flat(n).includes(name)
    && n.children.some((c) => c.tagName === 'BUTTON' && flat(c) === 'Рекомендовать'));
  assert.ok(row, 'в каталоге нет «Рекомендовать» у ' + name + ': ' + flat(ov()).slice(0, 300));
  row.children.find((c) => c.tagName === 'BUTTON' && flat(c) === 'Рекомендовать').click();
  await settle();
}

// ── Кабинет врача: «Направить на услуги» только рекомендует ─────────────────

test('врач: каталог «Рекомендовать», в смете нет плательщика, скидок и итога, второго шага нет', async () => {
  const { ov } = await open(DOCTOR, { recommend: true, referrerDoctorId: 2, title: 'Направить на услуги' });
  assert.ok(btnByText(ov(), 'Рекомендовать'), 'у услуг каталога нет кнопки «Рекомендовать»');
  assert.equal(btnByText(ov(), 'Добавить'), undefined, 'в режиме рекомендации осталась кнопка «Добавить»');
  const t = flat(ov());
  for (const gone of ['Кто платит', 'Итого', 'Далее: Подтверждение', 'Подтверждение']) {
    assert.ok(!t.includes(gone), `в режиме рекомендации видно «${gone}»`);
  }
});

test('врач: «Сохранить рекомендации» пишет открытые рекомендации с пометкой для регистратуры — ни визита, ни счёта', async () => {
  const { ov, saved } = await open(DOCTOR, { recommend: true, referrerDoctorId: 2 });
  await recommend(ov, 'Svc-АЧТВ');
  await recommend(ov, 'Svc-ОАК');
  const note = attrNodes(ov(), 'data-referral-note')[0];
  assert.ok(note, 'нет поля «Рекомендация для регистратуры»');
  note.value = 'натощак';
  note.dispatchEvent({ type: 'input', target: note, currentTarget: note });
  const save = btnByText(ov(), 'Сохранить рекомендации');
  assert.ok(save, 'нет кнопки «Сохранить рекомендации»');
  save.click();
  await settle();
  const rows = openRecs();
  assert.deepEqual(rows.map((r) => r.service_id), [41, 42]);
  assert.ok(rows.every((r) => r.status === 'pending' && r.notes === 'натощак' && r.recommended_by === 2), JSON.stringify(rows));
  assert.equal(DB.prepare('SELECT COUNT(*) n FROM visits').get().n, 0, 'врач завёл визит');
  assert.equal(DB.prepare('SELECT COUNT(*) n FROM visit_services').get().n, 0, 'врач завёл строки визита');
  assert.equal(DB.prepare('SELECT COUNT(*) n FROM invoices').get().n, 0, 'врач выставил счёт');
  assert.equal(saved.length, 1, 'кабинет не узнал о сохранённых рекомендациях');
  assert.deepEqual(saved[0].recommended.map((r) => r.service_id), [41, 42]);
  assert.equal(document.body.children.find(isWizard), undefined, 'окно не закрылось после сохранения');
});

test('врач: услуга, уже рекомендованная и не оформленная, второй раз не заводится', async () => {
  const { ov } = await open(DOCTOR, { recommend: true, referrerDoctorId: 2 }, { recs: [{ service_id: 41, name: 'Svc-АЧТВ' }] });
  await recommend(ov, 'Svc-АЧТВ');
  await recommend(ov, 'Svc-ОАК');
  btnByText(ov(), 'Сохранить рекомендации').click();
  await settle();
  assert.deepEqual(openRecs().map((r) => r.service_id), [41, 42], 'вторая открытая рекомендация той же услуги');
});

// ── Регистратура: рекомендации врача уже в смете, с галочкой ────────────────

test('регистратура: открытые рекомендации сразу в смете, отмечены и подписаны «Рекомендовано врачом · имя»', async () => {
  const { ov } = await open(REGISTRAR, {}, { recs: [{ service_id: 41, name: 'Svc-АЧТВ', notes: 'натощак' }, { service_id: 42, name: 'Svc-ОАК' }] });
  const tags = attrNodes(ov(), 'data-rec-line');
  assert.equal(tags.length, 2, 'рекомендации не встали в смету: ' + flat(ov()).slice(0, 400));
  assert.ok(tags.every((t) => flat(t) === 'Рекомендовано врачом · Врачев Доктор'), tags.map(flat).join(' | '));
  const ticks = attrNodes(ov(), 'data-doctor-rec-tick');
  assert.equal(ticks.length, 2, 'у рекомендаций нет галочек');
  assert.ok(ticks.every((t) => t.checked), 'рекомендации не отмечены сразу');
});

test('регистратура: снятая галочка убирает услугу из сметы, но рекомендация остаётся на следующий раз', async () => {
  const { ov } = await open(REGISTRAR, {}, { recs: [{ service_id: 41, name: 'Svc-АЧТВ' }, { service_id: 42, name: 'Svc-ОАК' }] });
  const tick = attrNodes(ov(), 'data-doctor-rec-tick').find((t) => flat(t.parentElement || t).includes('Svc-ОАК') || true);
  const oak = attrNodes(ov(), 'data-doctor-rec-tick').find((t) => {
    let p = t; for (let i = 0; i < 4 && p; i++) { if (flat(p).includes('Svc-ОАК')) return true; p = p.parentElement; } return false;
  });
  assert.ok(tick && oak, 'нет галочки у «Svc-ОАК»');
  oak.checked = false;
  oak.dispatchEvent({ type: 'change', target: oak, currentTarget: oak });
  await settle();
  const tags = attrNodes(ov(), 'data-rec-line').map(flat);
  assert.equal(tags.length, 1, 'снятая рекомендация осталась в смете');
  const again = attrNodes(ov(), 'data-doctor-rec-tick');
  assert.equal(again.length, 2, 'снятая рекомендация пропала из списка');
  assert.equal(again.filter((t) => t.checked).length, 1);
  assert.deepEqual(openRecs().map((r) => r.status), ['pending', 'pending'], 'снятие галочки закрыло рекомендацию');
});

test('регистратура: «Убрать» с подтверждением закрывает рекомендацию навсегда', async () => {
  const { ov } = await open(REGISTRAR, {}, { recs: [{ service_id: 41, name: 'Svc-АЧТВ' }, { service_id: 42, name: 'Svc-ОАК' }] });
  const drops = attrNodes(ov(), 'data-doctor-rec-drop');
  assert.equal(drops.length, 2, 'у рекомендаций нет «Убрать»');
  drops[drops.length - 1].click();
  await settle();
  const rows = openRecs();
  assert.equal(rows.filter((r) => r.status === 'cancelled').length, 1, 'рекомендация не закрыта: ' + JSON.stringify(rows));
  assert.equal(attrNodes(ov(), 'data-doctor-rec-tick').length, 1, 'убранная рекомендация осталась в списке');
  assert.equal(attrNodes(ov(), 'data-rec-line').length, 1, 'убранная рекомендация осталась в смете');
});
